// decodeNotification turns a method name and its params into the typed value.
func decodeNotification(method string, params json.RawMessage) (Notification, error) {
	switch method {
	case "minecraft:notification/server/started":
		return ServerStartedNotification{}, nil
	case "minecraft:notification/server/stopping":
		return ServerStoppingNotification{}, nil
	case "minecraft:notification/server/saving":
		return ServerSavingNotification{}, nil
	case "minecraft:notification/server/saved":
		return ServerSavedNotification{}, nil
	case "minecraft:notification/server/activity":
		return ServerActivityNotification{}, nil
	case "minecraft:notification/players/joined":
		var n PlayersJoinedNotification
		if err := decodeParam(params, "player", &n.Player); err != nil {
			return nil, err
		}
		return n, nil
	case "minecraft:notification/players/left":
		var n PlayersLeftNotification
		if err := decodeParam(params, "player", &n.Player); err != nil {
			return nil, err
		}
		return n, nil
	case "minecraft:notification/operators/added":
		var n OperatorsAddedNotification
		if err := decodeParam(params, "player", &n.Player); err != nil {
			return nil, err
		}
		return n, nil
	case "minecraft:notification/operators/removed":
		var n OperatorsRemovedNotification
		if err := decodeParam(params, "player", &n.Player); err != nil {
			return nil, err
		}
		return n, nil
	case "minecraft:notification/allowlist/added":
		var n AllowlistAddedNotification
		if err := decodeParam(params, "player", &n.Player); err != nil {
			return nil, err
		}
		return n, nil
	case "minecraft:notification/allowlist/removed":
		var n AllowlistRemovedNotification
		if err := decodeParam(params, "player", &n.Player); err != nil {
			return nil, err
		}
		return n, nil
	case "minecraft:notification/ip_bans/added":
		var n IPBansAddedNotification
		if err := decodeParam(params, "player", &n.Player); err != nil {
			return nil, err
		}
		return n, nil
	case "minecraft:notification/ip_bans/removed":
		var n IPBansRemovedNotification
		if err := decodeParam(params, "player", &n.Player); err != nil {
			return nil, err
		}
		return n, nil
	case "minecraft:notification/bans/added":
		var n BansAddedNotification
		if err := decodeParam(params, "player", &n.Player); err != nil {
			return nil, err
		}
		return n, nil
	case "minecraft:notification/bans/removed":
		var n BansRemovedNotification
		if err := decodeParam(params, "player", &n.Player); err != nil {
			return nil, err
		}
		return n, nil
	case "minecraft:notification/gamerules/updated":
		var n GamerulesUpdatedNotification
		if err := decodeParam(params, "gamerule", &n.Gamerule); err != nil {
			return nil, err
		}
		return n, nil
	case "minecraft:notification/server/status":
		var n ServerStatusNotification
		if err := decodeParam(params, "status", &n.Status); err != nil {
			return nil, err
		}
		return n, nil
	}
	return UnknownNotification{Method: method, Params: params}, nil
}
